"""JSON syntax support only; no controller schema or domain evaluator."""
import json


def unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def decode(text):
    return json.loads(text, object_pairs_hook=unique,
                      parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
"""Incomplete extension point for the persistent reservation/compilation service."""


