"""Persistent reservation and schedule compilation controller.

Implements the ``forest-controller/3`` contract of PROTOCOL.md version 3.0.0:
lease bookkeeping with revisions, ownership, edits, expiry and replay
history, plus compilation of recurring nonuniform allgather proposals into
weighted logical trees and compressed physical unicast routes.
"""

import re

from compiler import compile_plan

ID_RE = re.compile(r"\A[A-Za-z0-9_.-]{1,32}\Z")

MAXQ = 10 ** 12
MAX_NODE = 47
MAX_LINK = 127
MAX_PERIOD = 10 ** 6
MAX_BOOKINGS = 128
MAX_LINKS = 128
MAX_ENVELOPE = 128
MAX_ENVELOPE_TOTAL = 2048
MAX_PARTICIPANTS = 32
MAX_TICKS = 8
MAX_CHANGES = 128


class Invalid(Exception):
    """Schema or JSON level violation: the command is rejected as invalid."""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _int(value, low, high):
    if not _is_int(value) or value < low or value > high:
        raise Invalid()
    return value


def _name(value):
    if not isinstance(value, str) or ID_RE.match(value) is None:
        raise Invalid()
    return value


def _array(value, low=0, high=None):
    if not isinstance(value, list):
        raise Invalid()
    if len(value) < low:
        raise Invalid()
    if high is not None and len(value) > high:
        raise Invalid()
    return value


def _object(value, fields):
    if not isinstance(value, dict):
        raise Invalid()
    if set(value.keys()) != set(fields):
        raise Invalid()
    return value


def _pair(value):
    if not isinstance(value, list) or len(value) != 2:
        raise Invalid()
    return value


class Lease:
    """A committed reservation: an envelope held over a half open window."""

    __slots__ = ("ident", "owner", "start", "end", "rates")

    def __init__(self, ident, owner, start, end, rates):
        self.ident = ident
        self.owner = owner
        self.start = start
        self.end = end
        self.rates = rates


class Controller:
    """The whole service state."""

    def __init__(self):
        self.loaded = False
        self.size = 0
        self.links = []
        self.caps = []
        self.leases = {}
        self.records = {}
        self.rev = 0
        self.now = 0
        self.link_leases = {}

    # -- helpers ------------------------------------------------------------

    def _error(self, code):
        return {"status": "error", "code": code, "rev": self.rev}

    def _stale(self):
        return {"status": "stale", "rev": self.rev}

    def _not_loaded(self):
        return {"status": "error", "code": "NOT_LOADED", "rev": 0}

    def _used(self, link, tick):
        """Reserved rate on ``link`` at ``tick`` from all active live leases."""
        total = 0
        for lease in self.link_leases.get(link, ()):
            if lease.start <= tick < lease.end:
                total += lease.rates.get(link, 0)
        return total

    def _booked(self, lease):
        self.leases[lease.ident] = lease
        for link in lease.rates:
            self.link_leases.setdefault(link, []).append(lease)

    def _release(self, ident):
        lease = self.leases.pop(ident, None)
        if lease is None:
            return
        for link in list(lease.rates):
            bucket = self.link_leases.get(link)
            if bucket and lease in bucket:
                bucket.remove(lease)
                if not bucket:
                    del self.link_leases[link]

    # -- operations ---------------------------------------------------------

    def op_about(self, request):
        _object(request, ("op",))
        return {"status": "ok", "protocol": "forest-controller/3"}

    def op_load(self, request):
        _object(request, ("op", "n", "links", "bookings"))
        size = _int(request["n"], 2, 48)
        links = []
        caps = []
        pairs = set()
        for item in _array(request["links"], 0, MAX_LINKS):
            if not isinstance(item, list) or len(item) != 3:
                raise Invalid()
            u = _int(item[0], 0, MAX_NODE)
            v = _int(item[1], 0, MAX_NODE)
            cap = _int(item[2], 0, MAXQ)
            if u == v or u >= size or v >= size:
                raise Invalid()
            key = (u, v) if u < v else (v, u)
            if key in pairs:
                raise Invalid()
            pairs.add(key)
            links.append((u, v))
            caps.append(cap)

        bookings = []
        seen = set()
        total_envelope = 0
        for item in _array(request["bookings"], 0, MAX_BOOKINGS):
            _object(item, ("id", "owner", "window", "envelope"))
            ident = _name(item["id"])
            owner = _name(item["owner"])
            if ident in seen:
                raise Invalid()
            seen.add(ident)
            window = item["window"]
            if not isinstance(window, list) or len(window) != 2:
                raise Invalid()
            start = _int(window[0], 0, MAXQ)
            end = _int(window[1], 0, MAXQ)
            if start >= end:
                raise Invalid()
            rates = {}
            for pair in _array(item["envelope"], 0, MAX_ENVELOPE):
                _pair(pair)
                link = _int(pair[0], 0, MAX_LINK)
                rate = _int(pair[1], 1, MAXQ)
                if link >= len(links):
                    raise Invalid()
                if link in rates:
                    raise Invalid()
                rates[link] = rate
            total_envelope += len(rates)
            if total_envelope > MAX_ENVELOPE_TOTAL:
                raise Invalid()
            bookings.append((ident, owner, start, end, rates))

        if self.loaded:
            return self._error("ALREADY_LOADED")

        # structural load relation: no tick and link may be overbooked
        events = {}
        for ident, owner, start, end, rates in bookings:
            for link, rate in rates.items():
                bucket = events.setdefault(link, [])
                bucket.append((start, rate))
                bucket.append((end, -rate))
        for link, bucket in events.items():
            bucket.sort()
            running = 0
            for tick, delta in bucket:
                running += delta
                if running > caps[link]:
                    raise Invalid()

        self.loaded = True
        self.size = size
        self.links = links
        self.caps = caps
        self.leases = {}
        self.link_leases = {}
        self.records = {}
        self.rev = 0
        self.now = 0
        for ident, owner, start, end, rates in bookings:
            lease = Lease(ident, owner, start, end, rates)
            self._booked(lease)
            self.records[ident] = {
                "kind": "load",
                "owner": owner,
                "payload": None,
                "base_rev": 0,
                "outcome": None,
            }
        return {"status": "ok", "rev": 0, "now": 0}

    def op_audit(self, request):
        _object(request, ("op", "at"))
        ticks = [_int(t, 0, MAXQ) for t in _array(request["at"], 0, MAX_TICKS)]
        if not self.loaded:
            return self._not_loaded()
        for tick in ticks:
            if tick < self.now:
                return self._error("TIME")
        leases = sorted(self.leases)
        samples = []
        for tick in ticks:
            row = []
            for link in range(len(self.caps)):
                row.append(self.caps[link] - self._used(link, tick))
            samples.append([tick, row])
        return {
            "status": "ok",
            "rev": self.rev,
            "now": self.now,
            "leases": leases,
            "samples": samples,
        }

    def op_advance(self, request):
        _object(request, ("op", "time"))
        tick = _int(request["time"], 0, MAXQ)
        if not self.loaded:
            return self._not_loaded()
        if tick < self.now:
            return self._error("TIME")
        expired = sorted(
            ident for ident, lease in self.leases.items() if lease.end <= tick
        )
        for ident in expired:
            self._release(ident)
            record = self.records.get(ident)
            if record is not None:
                record["kind"] = "dead"
        self.now = tick
        self.rev += 1
        return {"status": "ok", "rev": self.rev, "now": tick, "expired": expired}

    def op_edit(self, request):
        _object(request, ("op", "rev", "changes", "force"))
        expected = _int(request["rev"], 0, MAXQ)
        force = request["force"]
        if not isinstance(force, bool):
            raise Invalid()
        changes = {}
        for item in _array(request["changes"], 0, MAX_CHANGES):
            _pair(item)
            link = _int(item[0], 0, MAX_LINK)
            cap = _int(item[1], 0, MAXQ)
            if link in changes:
                raise Invalid()
            changes[link] = cap
        if not self.loaded:
            return self._not_loaded()
        if expected != self.rev:
            return self._stale()
        for link in changes:
            if link >= len(self.caps):
                return self._error("REFERENCE")

        proposed = list(self.caps)
        for link, cap in changes.items():
            proposed[link] = cap

        if not force:
            for link in sorted(changes):
                cap = proposed[link]
                for tick in self._ticks_from(self.now):
                    used = self._used(link, tick)
                    if used > cap:
                        return {
                            "status": "blocked",
                            "rev": self.rev,
                            "link": link,
                            "time": tick,
                            "used": used,
                            "capacity": cap,
                        }

        cancelled = []
        if force:
            for link in sorted(changes):
                if proposed[link] < self.caps[link]:
                    for ident, lease in self.leases.items():
                        if lease.rates.get(link, 0) > 0 and ident not in cancelled:
                            cancelled.append(ident)
            for ident in cancelled:
                self._release(ident)
                record = self.records.get(ident)
                if record is not None:
                    record["kind"] = "dead"
        self.caps = proposed
        self.rev += 1
        return {"status": "ok", "rev": self.rev, "cancelled": sorted(cancelled)}

    def _ticks_from(self, floor):
        """Ticks at which the reserved rate can be maximal from ``floor`` on."""
        ticks = {floor}
        for lease in self.leases.values():
            if lease.start > floor:
                ticks.add(lease.start)
        return sorted(ticks)

    def _ticks_within(self, start, end):
        """Ticks at which the reserved rate can be maximal inside [start,end)."""
        ticks = {start}
        for lease in self.leases.values():
            if start < lease.start < end:
                ticks.add(lease.start)
        return sorted(ticks)

    def op_prepare(self, request):
        _object(
            request,
            ("op", "id", "owner", "window", "period", "participants", "envelope", "rev"),
        )
        ident = _name(request["id"])
        owner = _name(request["owner"])
        window = request["window"]
        if not isinstance(window, list) or len(window) != 2:
            raise Invalid()
        start = _int(window[0], 0, MAXQ)
        end = _int(window[1], 0, MAXQ)
        if start >= end:
            raise Invalid()
        period = _int(request["period"], 1, MAX_PERIOD)
        demands = {}
        for item in _array(request["participants"], 2, MAX_PARTICIPANTS):
            if not isinstance(item, list) or len(item) != 2:
                raise Invalid()
            vertex = _int(item[0], 0, MAX_NODE)
            demand = _int(item[1], 0, MAXQ)
            if vertex in demands:
                raise Invalid()
            demands[vertex] = demand
        if sum(demands.values()) <= 0:
            raise Invalid()
        envelope = {}
        for pair in _array(request["envelope"], 0, MAX_ENVELOPE):
            _pair(pair)
            link = _int(pair[0], 0, MAX_LINK)
            rate = _int(pair[1], 1, MAXQ)
            if link in envelope:
                raise Invalid()
            envelope[link] = rate
        expected = _int(request["rev"], 0, MAXQ)
        if not self.loaded:
            return self._not_loaded()

        payload = (
            owner,
            start,
            end,
            period,
            expected,
            tuple(sorted(demands.items())),
            tuple(sorted(envelope.items())),
        )

        record = self.records.get(ident)
        if record is not None:
            if record.get("payload") is not None and record["payload"] == payload:
                return {
                    "status": "replay",
                    "id": ident,
                    "rev": self.rev,
                    "base_rev": record["base_rev"],
                    "outcome": record["outcome"],
                }
            return self._error("CONFLICT")

        if expected != self.rev:
            return self._stale()
        for vertex in demands:
            if vertex >= self.size:
                return self._error("REFERENCE")
        for link in envelope:
            if link >= len(self.links):
                return self._error("REFERENCE")
        if start < self.now:
            return self._error("TIME")
        if (end - start) % period != 0:
            return self._error("WINDOW")

        record = {
            "kind": "prepared",
            "owner": owner,
            "payload": payload,
            "base_rev": self.rev,
            "outcome": "prepared",
            "window": (start, end),
            "envelope": dict(envelope),
        }

        # the offered envelope has to fit into the current lease book
        witness = None
        for link in sorted(envelope):
            rate = envelope[link]
            capacity = self.caps[link]
            for tick in self._ticks_within(start, end):
                used = self._used(link, tick) + rate
                if used > capacity:
                    witness = (link, tick, used, capacity)
                    break
            if witness is not None:
                break
        if witness is not None:
            link, tick, used, capacity = witness
            record["kind"] = "denied"
            record["outcome"] = "denied"
            self.records[ident] = record
            return {
                "status": "denied",
                "id": ident,
                "rev": self.rev,
                "kind": "capacity",
                "link": link,
                "time": tick,
                "used": used,
                "capacity": capacity,
            }

        plan, cut = compile_plan(
            self.size,
            self.links,
            envelope,
            period,
            sorted(demands),
            demands,
        )
        if plan is None:
            record["kind"] = "denied"
            record["outcome"] = "denied"
            self.records[ident] = record
            return {
                "status": "denied",
                "id": ident,
                "rev": self.rev,
                "kind": "cut",
                "cut": list(cut),
            }
        self.records[ident] = record
        return {
            "status": "prepared",
            "id": ident,
            "rev": self.rev,
            "plan": plan,
        }

    def op_commit(self, request):
        _object(request, ("op", "id", "owner", "rev"))
        ident = _name(request["id"])
        owner = _name(request["owner"])
        expected = _int(request["rev"], 0, MAXQ)
        if not self.loaded:
            return self._not_loaded()
        record = self.records.get(ident)
        if record is None:
            return self._error("MISSING")
        if record.get("owner") != owner:
            return self._error("OWNER")
        if ident in self.leases:
            return {"status": "ok", "id": ident, "rev": self.rev, "replay": True}
        if record["kind"] == "denied":
            return self._error("DENIED")
        if record["kind"] == "dead":
            return self._error("GONE")
        if expected != self.rev or record["base_rev"] != self.rev:
            return self._stale()
        start, end = record["window"]
        lease = Lease(ident, owner, start, end, dict(record["envelope"]))
        self._booked(lease)
        record["kind"] = "committed"
        self.rev += 1
        return {"status": "ok", "id": ident, "rev": self.rev, "replay": False}

    def op_cancel(self, request):
        _object(request, ("op", "id", "owner", "rev"))
        ident = _name(request["id"])
        owner = _name(request["owner"])
        expected = _int(request["rev"], 0, MAXQ)
        if not self.loaded:
            return self._not_loaded()
        if expected != self.rev:
            return self._stale()
        lease = self.leases.get(ident)
        if lease is None:
            return self._error("MISSING")
        if lease.owner != owner:
            return self._error("OWNER")
        self._release(ident)
        record = self.records.get(ident)
        if record is not None:
            record["kind"] = "dead"
        self.rev += 1
        return {"status": "ok", "rev": self.rev, "released": ident}


CONTROLLER = Controller()

OPERATIONS = {
    "about": Controller.op_about,
    "load": Controller.op_load,
    "audit": Controller.op_audit,
    "advance": Controller.op_advance,
    "edit": Controller.op_edit,
    "prepare": Controller.op_prepare,
    "commit": Controller.op_commit,
    "cancel": Controller.op_cancel,
}


def handle(request):
    """Process one decoded request object and return the reply object."""
    if not isinstance(request, dict):
        return {"status": "invalid"}
    op = request.get("op")
    if not isinstance(op, str):
        return {"status": "invalid"}
    handler = OPERATIONS.get(op)
    if handler is None:
        return {"status": "invalid"}
    try:
        return handler(CONTROLLER, request)
    except Invalid:
        return {"status": "invalid"}
