"""Compilation of recurring nonuniform allgather reservations.

The compiler turns a weighted allgather proposal into a *plan*:

``trees``    weighted logical out-trees over the participant set (one record
             per demanded root, weight = that root's chunk demand),
``routes``   per ordered participant pair the exact number of unicast chunk
             copies that the logical trees require, each bound to a recipe,
``recipes``  a shared acyclic serial-route circuit; every leaf is a single
             directed physical link traversal.

Ordinary (non participant) vertices are pure forwarders: they may never
multicast or aggregate.  A recipe therefore only ever concatenates walks at
non participant vertices, and every leaf occurrence is charged with the full
multiplicity of the route that references it.

All arithmetic is exact integer arithmetic.
"""

import heapq
from collections import deque

MAX_TREE_RECORDS = 8192
MAX_ROUTE_RECORDS = 32768
MAX_RECIPE_NODES = 65536
MAX_SPLITS = 64


# ---------------------------------------------------------------------------
# graph helpers
# ---------------------------------------------------------------------------

def _adjacency(n, links, envelope):
    """Directed adjacency over the offered links only."""
    adj = [[] for _ in range(n)]
    for link in sorted(envelope):
        u, v = links[link]
        adj[u].append((link, 0, v))
        adj[v].append((link, 1, u))
    return adj


def _bfs_tree(adj, source, expandable):
    """Breadth first tree that only expands ordinary forwarding vertices."""
    parent = {source: None}
    order = [source]
    queue = deque([source])
    while queue:
        x = queue.popleft()
        for link, direction, y in adj[x]:
            if y in parent:
                continue
            parent[y] = (x, link, direction)
            order.append(y)
            if y in expandable:
                queue.append(y)
    return parent, order


def _widest_path(adj, source, target, ordinary, residual):
    """Path from ``source`` to ``target`` with the largest residual bottleneck.

    Only ordinary vertices may be used in the interior of the walk, so a
    participant that is not the target terminates the search.
    """
    best = {source: (1 << 62, None)}
    heap = [(-(1 << 62), source)]
    while heap:
        neg, x = heapq.heappop(heap)
        value = -neg
        if x in best and best[x][0] > value:
            continue
        if x == target:
            break
        for link, direction, y in adj[x]:
            room = residual.get((link, direction), 0)
            if room <= 0:
                continue
            if y != target and y not in ordinary:
                continue
            candidate = value if value < room else room
            if y in best and best[y][0] >= candidate:
                continue
            best[y] = (candidate, (x, link, direction))
            heapq.heappush(heap, (-candidate, y))
    if target not in best:
        return None, 0
    chain = []
    node = target
    while node != source:
        value, step = best[node]
        prev, link, direction = step
        chain.append((link, direction))
        node = prev
    chain.reverse()
    return chain, best[target][0]


class _Flow:
    """Tiny exact integer maximum flow (Dinic) over an explicit arc list."""

    __slots__ = ("n", "to", "cap", "head", "nxt")

    def __init__(self, n):
        self.n = n
        self.to = []
        self.cap = []
        self.head = [-1] * n
        self.nxt = []

    def add(self, u, v, c):
        if c <= 0:
            return
        self.to.append(v)
        self.cap.append(c)
        self.nxt.append(self.head[u])
        self.head[u] = len(self.to) - 1
        self.to.append(u)
        self.cap.append(0)
        self.nxt.append(self.head[v])
        self.head[v] = len(self.to) - 1

    def _bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        queue = deque([s])
        while queue:
            x = queue.popleft()
            e = self.head[x]
            while e != -1:
                if self.cap[e] > 0 and level[self.to[e]] < 0:
                    level[self.to[e]] = level[x] + 1
                    queue.append(self.to[e])
                e = self.nxt[e]
        return level

    def _dfs(self, x, t, f, level, it):
        if x == t:
            return f
        while it[x] != -1:
            e = it[x]
            y = self.to[e]
            if self.cap[e] > 0 and level[y] == level[x] + 1:
                d = self._dfs(y, t, f if f < self.cap[e] else self.cap[e], level, it)
                if d > 0:
                    self.cap[e] -= d
                    self.cap[e ^ 1] += d
                    return d
            it[x] = self.nxt[e]
        return 0

    def maxflow(self, s, t):
        flow = 0
        while True:
            level = self._bfs(s, t)
            if level[t] < 0:
                return flow
            it = list(self.head)
            while True:
                f = self._dfs(s, t, 1 << 62, level, it)
                if f == 0:
                    break
                flow += f

    def source_side(self, s):
        """Vertices reachable from ``s`` in the residual graph (a min cut side)."""
        seen = [False] * self.n
        seen[s] = True
        stack = [s]
        while stack:
            x = stack.pop()
            e = self.head[x]
            while e != -1:
                if self.cap[e] > 0 and not seen[self.to[e]]:
                    seen[self.to[e]] = True
                    stack.append(self.to[e])
                e = self.nxt[e]
        return seen


# ---------------------------------------------------------------------------
# deficient cut witnesses
# ---------------------------------------------------------------------------

def find_deficient_cut(n, links, caps, participants, demands):
    """Search for a vertex set ``S`` witnessing that admission is impossible.

    The witness condition of the protocol is strict::

        sum(p*b_l for links with exactly one endpoint in S)
            < sum(r_v for participants v in S)

    With ``C`` the participant set and ``D`` the total demand this is
    equivalent to ``sum_{v in C, v not in S} r_v + cross(S) < D`` where
    ``cross(S)`` is the total capacity of the links leaving ``S``.  That is a
    minimum cut of the network that connects a super source to every
    participant with capacity ``r_v`` and gives every physical link its
    per-period capacity in both directions.  Fixing one participant on the
    sink side keeps the witness admissible (it must not contain every
    participant), so the search is exact.

    Returns ``(cut, deficit)`` where ``cut`` is ``None`` when no admissible
    witness exists and ``deficit`` is the best (possibly non positive) slack
    ``sum(r_v in S) - cross(S)``.
    """
    part = sorted(participants)
    total = sum(demands[v] for v in part)
    if not part:
        return None, 0

    src = n
    best_cut = None
    best_deficit = None
    for sink in part:
        flow = _Flow(n + 1)
        for v in part:
            flow.add(src, v, demands[v])
        for link, rate in caps.items():
            u, w = links[link]
            flow.add(u, w, rate)
            flow.add(w, u, rate)
        flow.maxflow(src, sink)
        seen = flow.source_side(src)
        cut = [v for v in range(n) if seen[v]]
        inside = set(cut)
        demand = sum(demands[v] for v in part if seen[v])
        cross = 0
        for link, rate in caps.items():
            u, w = links[link]
            if (u in inside) != (w in inside):
                cross += rate
        deficit = demand - cross
        if best_deficit is None or deficit > best_deficit:
            best_deficit = deficit
            best_cut = cut
        if deficit > 0:
            return cut, deficit
    return None, (best_deficit if best_deficit is not None else 0)


# ---------------------------------------------------------------------------
# plan construction
# ---------------------------------------------------------------------------

def _logical_trees(participants, demands, reach, variant):
    """Weighted logical out-trees of the participant graph, one per root."""
    part = set(participants)
    roots = [v for v in participants if demands[v] > 0]
    trees = {}
    loads = {}
    for root in roots:
        parent = {root: None}
        order = [root]
        queue = deque([root])
        while queue:
            x = queue.popleft()
            targets = reach[x]
            if variant == "direct" and x != root:
                targets = [y for y in targets if y != root]
            for y in targets:
                if y in parent:
                    continue
                parent[y] = x
                order.append(y)
                queue.append(y)
        if len(parent) != len(part):
            return None, None
        trees[root] = parent
        weight = demands[root]
        for node in order[1:]:
            key = (parent[node], node)
            loads[key] = loads.get(key, 0) + weight
    return trees, loads


def _route(adj, ordinary, caps, logical):
    """Route every logical edge over the physical fabric.

    Each ordered participant pair carries exactly the number of chunk copies
    that the logical trees require.  The greedy engine always takes the walk
    with the largest remaining bottleneck and splits a pair over several walks
    when a single one cannot carry the whole count.
    """
    residual = {}
    for link, cap in caps.items():
        residual[(link, 0)] = cap
        residual[(link, 1)] = cap
    routes = []
    pairs = sorted(logical.items(), key=lambda kv: (-kv[1], kv[0]))
    for (u, v), demand in pairs:
        need = demand
        splits = 0
        while need > 0:
            chain, room = _widest_path(adj, u, v, ordinary, residual)
            if chain is None:
                return None
            take = need if need < room else room
            if take <= 0:
                return None
            routes.append((u, v, take, chain))
            for link, direction in chain:
                key = (link, direction)
                residual[key] -= take
            need -= take
            splits += 1
            if splits > MAX_SPLITS:
                return None
            if len(routes) > MAX_ROUTE_RECORDS:
                return None
    return routes


def _recipes_for(routes):
    """Build the shared serial route circuit for the routed walks."""
    recipes = []
    leaves = {}
    prefixes = {}

    def leaf_of(link, direction):
        key = (link, direction)
        node = leaves.get(key)
        if node is None:
            node = len(recipes)
            recipes.append([0, link, direction])
            leaves[key] = node
        return node

    for u, v, count, chain in routes:
        prefix = ()
        node = None
        for link, direction in chain:
            leaf = leaf_of(link, direction)
            if node is None:
                node = leaf
            else:
                key = prefix
                node = prefixes.get(key)
                if node is None:
                    node = len(recipes)
                    recipes.append([1, node, leaf])
                    prefixes[key] = node
            prefix = prefix + ((link, direction),)
            if len(recipes) > MAX_RECIPE_NODES:
                return None, None
        if node is None:
            return None, None
    return recipes, prefixes


def _plan_loads(plan, links):
    """Aggregate physical load of a plan, keyed by (link, direction)."""
    recipes = plan["recipes"]
    memo = {}

    def leaves(nid):
        cached = memo.get(nid)
        if cached is not None:
            return cached
        node = recipes[nid]
        if node[0] == 0:
            out = [(node[1], node[2])]
        else:
            out = leaves(node[1]) + leaves(node[2])
        memo[nid] = out
        return out

    loads = {}
    for u, v, count, recipe in plan["routes"]:
        for link, direction in leaves(recipe):
            key = (link, direction)
            loads[key] = loads.get(key, 0) + count
    return loads


def validate_plan(plan, n, links, caps, participants, demands, period):
    """Check a plan against every structural rule of the protocol."""
    part = set(participants)
    total = sum(demands.values())
    trees = plan["trees"]
    routes = plan["routes"]
    recipes = plan["recipes"]
    if len(trees) > MAX_TREE_RECORDS or len(routes) > MAX_ROUTE_RECORDS:
        return False
    if len(recipes) > MAX_RECIPE_NODES:
        return False

    # --- recipes -----------------------------------------------------------
    ends = {}

    def walk(nid, stack):
        if nid in stack:
            return None
        if nid in ends:
            return ends[nid]
        if not isinstance(nid, int) or isinstance(nid, bool):
            return None
        if nid < 0 or nid >= len(recipes):
            return None
        node = recipes[nid]
        if not isinstance(node, list) or len(node) not in (2, 3):
            return None
        if node[0] == 0:
            if len(node) != 3:
                return None
            link, direction = node[1], node[2]
            if not isinstance(link, int) or isinstance(link, bool):
                return None
            if not isinstance(direction, int) or isinstance(direction, bool):
                return None
            if link < 0 or link >= len(links) or direction not in (0, 1):
                return None
            u, v = links[link]
            ends[nid] = (u, v) if direction == 0 else (v, u)
            return ends[nid]
        if node[0] == 1:
            if len(node) != 3:
                return None
            left = walk(node[1], stack | {nid})
            if left is None:
                return None
            right = walk(node[2], stack | {nid})
            if right is None:
                return None
            if left[1] != right[0]:
                return None
            if left[1] in part:
                return None
            ends[nid] = (left[0], right[1])
            return ends[nid]
        return None

    for nid in range(len(recipes)):
        if walk(nid, frozenset()) is None:
            return False

    # --- trees -------------------------------------------------------------
    weight = {}
    logical = {}
    for record in trees:
        if not isinstance(record, list) or len(record) != 3:
            return False
        root, count, edges = record
        if not isinstance(root, int) or isinstance(root, bool):
            return False
        if root not in part:
            return False
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        if count <= 0 or count > total:
            return False
        if not isinstance(edges, list) or len(edges) != len(part) - 1:
            return False
        indeg = {}
        adj = {}
        seen = set()
        for edge in edges:
            if not isinstance(edge, list) or len(edge) != 2:
                return False
            u, v = edge
            if not isinstance(u, int) or isinstance(u, bool):
                return False
            if not isinstance(v, int) or isinstance(v, bool):
                return False
            if u not in part or v not in part or u == v:
                return False
            if (u, v) in seen:
                return False
            seen.add((u, v))
            indeg[v] = indeg.get(v, 0) + 1
            adj.setdefault(u, []).append(v)
        if indeg.get(root, 0) != 0:
            return False
        for node in part:
            if node != root and indeg.get(node, 0) != 1:
                return False
        stack = [root]
        visited = {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in visited:
                    visited.add(y)
                    stack.append(y)
        if visited != part:
            return False
        weight[root] = weight.get(root, 0) + count
        for edge in edges:
            key = (edge[0], edge[1])
            logical[key] = logical.get(key, 0) + count

    for node in part:
        if demands[node] == 0:
            if weight.get(node, 0) != 0:
                return False
        elif weight.get(node, 0) != demands[node]:
            return False

    # --- routes ------------------------------------------------------------
    routed = {}
    for record in routes:
        if not isinstance(record, list) or len(record) != 4:
            return False
        u, v, count, recipe = record
        if not isinstance(u, int) or isinstance(u, bool):
            return False
        if not isinstance(v, int) or isinstance(v, bool):
            return False
        if u not in part or v not in part or u == v:
            return False
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        if count <= 0 or count > total:
            return False
        if not isinstance(recipe, int) or isinstance(recipe, bool):
            return False
        if recipe < 0 or recipe >= len(recipes):
            return False
        walk_end = ends.get(recipe)
        if walk_end is None or walk_end[0] != u or walk_end[1] != v:
            return False
        key = (u, v)
        routed[key] = routed.get(key, 0) + count
    for key, value in logical.items():
        if routed.get(key, 0) != value:
            return False
    for key, value in routed.items():
        if logical.get(key, 0) != value:
            return False

    # --- physical load -----------------------------------------------------
    loads = _plan_loads(plan, links)
    for (link, direction), value in loads.items():
        if value > caps.get(link, 0):
            return False
    return True


def _try_variant(n, links, envelope, period, participants, demands, variant):
    """Build one concrete plan; returns the plan or ``None``."""
    part = set(participants)
    ordinary = set(range(n)) - part
    adj = _adjacency(n, links, envelope)
    caps = {link: period * rate for link, rate in envelope.items()}

    # physical reachability between participants (ordinary vertices only)
    reach = {}
    for u in participants:
        parent, _order = _bfs_tree(adj, u, ordinary)
        reach[u] = [w for w in parent if w in part and w != u]

    trees, logical = _logical_trees(participants, demands, reach, variant)
    if trees is None:
        return None

    routed = _route(adj, ordinary, caps, logical)
    if routed is None:
        return None

    recipes, prefixes = _recipes_for(routed)
    if recipes is None:
        return None

    # route records reference the recipe of their walk
    route_records = []
    for u, v, count, chain in routed:
        node = None
        prefix = ()
        for link, direction in chain:
            if node is None:
                node = _leaf_id(recipes, link, direction)
            else:
                node = prefixes[prefix]
            prefix = prefix + ((link, direction),)
        route_records.append([u, v, count, node])

    tree_records = []
    for root in sorted(trees):
        parent = trees[root]
        edges = []
        for node, prev in sorted(parent.items()):
            if node != root:
                edges.append([prev, node])
        tree_records.append([root, demands[root], edges])

    plan = {"trees": tree_records, "routes": route_records, "recipes": recipes}
    if not validate_plan(plan, n, links, caps, participants, demands, period):
        return None
    return plan


def _leaf_id(recipes, link, direction):
    for index, node in enumerate(recipes):
        if node[0] == 0 and node[1] == link and node[2] == direction:
            return index
    return None


def compile_plan(n, links, envelope, period, participants, demands):
    """Compile a proposal.

    Returns ``(plan, cut)``.  ``plan`` is a valid plan when the proposal is
    admissible, otherwise ``None`` and ``cut`` holds the vertices of a
    deficient cut witness (best effort when the witness cannot be made
    strictly deficient).
    """
    caps = {link: period * rate for link, rate in envelope.items()}
    cut, _deficit = find_deficient_cut(n, links, caps, participants, demands)
    if cut is not None:
        return None, cut
    for variant in ("relay", "direct", "relay2"):
        plan = _try_variant(n, links, envelope, period, participants, demands, variant)
        if plan is not None:
            return plan, None
    if cut is None:
        # no strictly deficient witness exists; return the closest one so that
        # the denial still points at the bottleneck.
        cut, _deficit = find_deficient_cut(n, links, caps, participants, demands)
        if cut is None:
            cut = sorted(participants)[:1]
    return None, cut
