import re

from compiler import compile_plan

ID_RE = re.compile(r"\A[A-Za-z0-9_.-]{1,32}\Z")

MAXQ = 10 ** 12
MAX_NODE = 47
MAX_LINK = 127
MAX_PERIOD = 10 ** 6
MAX_BOOKINGS = 128
